# shellcheck disable=SC2059 # callers pass fixed format strings (like printf)
larch_errf() {
    if [ "${LARCH_QUIET_PID:-}" = "$$" ]; then
        printf "$@" >&4
    else
        printf "$@" >&2
    fi
}

emit() {
    if [ "${LARCH_QUIET_PID:-}" = "$$" ]; then
        printf '%s\n' "$*" >&3
    else
        printf '%s\n' "$*"
    fi
}

emit_kv() {
    local key=$1 value=${2-}
    if [ "${LARCH_QUIET_PID:-}" = "$$" ]; then
        printf '%s=%s\n' "$key" "$value" >&3
    else
        printf '%s=%s\n' "$key" "$value"
    fi
}

emit_breadcrumb() {
    if larch_quiet_truthy "${LARCH_QUIET_BREADCRUMBS:-}"; then
        emit "$*"
    else
        printf '%s\n' "$*"
    fi
}

